   [70]={next_id=71, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="小哥你是想说条件太简陋了对吧……没办法，在这个地方，能有个医务站已经不错了。", msg_color="", msg_size=0, talker="拉文", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [71]={next_id=72, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="当初我们与凯瑞公司抗议了很久，他们才同意帮助我们建立医疗站，可实际情况你也看到了。", msg_color="", msg_size=0, talker="拉文", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [72]={next_id=73, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="他的语气里没有愤怒，只有一种被磨平了棱角的疲惫。就像一个已经重复了太多遍的故事，连讲的人都觉得厌倦。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [73]={next_id=74, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="但我不会放弃，哪怕再困难，哪怕前路看不到希望。但只要我们不放弃，把大家团结在一起。", msg_color="", msg_size=0, talker="拉文", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [74]={next_id=75, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我相信，总有一天，我们能重新夺回属于我们的家园。", msg_color="", msg_size=0, talker="拉文", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
