   [88]={next_id=89, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="拉文从工装口袋里掏出一个皱巴巴的小纸包打开，里面是一小撮绿色的粉末。细得像面粉，在晨光中泛着一种不自然的荧光。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
