   [133]={next_id=134, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="远处突然传来一声尖叫。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [134]={next_id=135, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="不是普通的喊叫，是那种只有在看到死亡时才会发出的、撕心裂肺的尖叫。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [135]={next_id=136, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="蛰吻和你对视一眼，同时朝声音传来的方向冲去。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
